@Test
    public void testConvertRegularExpr() {
        String result = StringUtil.convertRegularExpr("\\t\\r\\n");
        Assert.assertEquals(result, "\t\r\n");

        result = StringUtil.convertRegularExpr(null);
        Assert.assertEquals(result, "");
    }

